#!/usr/bin/env bash
#
# nexum-bridge-burn-scanner.sh
# =============================================================================
# THE real fix for "bridge stuck In progress after refresh". A backend job that
# recovers the burn tx hash from the chain, so a browser refresh mid-burn no
# longer strands the transfer.
#
# HOW IT WORKS: a bridge stuck in 'burning' with no burn_tx means the burn was
# signed (and landed on-chain) but the browser never recorded the hash. The
# completion path needs that hash to fetch Circle's attestation. This scanner
# reads the SOURCE chain's TokenMessenger for the user's CCTP V2 DepositForBurn
# event, matches it to the row (depositor=wallet, amount, destinationDomain,
# mintRecipient), and backfills burn_tx. The row then moves to 'attesting' and
# the existing mint path completes it. The chain is the source of truth, so the
# browser surviving no longer matters.
#
# Verified against Circle CCTP V2 docs (DepositForBurn event signature, Arc
# domain 26, single testnet TokenMessengerV2) and the live bridge repository.
# Matching is STRICT: ambiguous (two identical burns) are skipped, never
# guessed, so a wrong hash is never attached.
#
# WHAT THIS DELIVERS (nexum-api only, ADDITIVE):
#   1. services/bridge/burnScanner.ts   (NEW) - findBurnTx(rec): scans source
#      chain, returns the matching burn tx hash or null. Per-chain RPC map;
#      TokenMessenger + lookback overridable via env. Never throws.
#   2. services/bridge/repository.ts    (EDIT) - + listStuckBurning(minAge):
#      rows in 'burning' with no burn_tx older than a grace period (default 2m).
#   3. services/bridge/reconciler.ts    (EDIT) - reconcileOnce() now also scans
#      stuck-burning rows and backfills via markBurned. Runs on the EXISTING
#      bridge reconciler cron (already started at boot) - no new wiring.
#
# NO redeploy of the contract, NO frontend change. API only. Fully automatic.
# Optional env: CCTP_TOKEN_MESSENGER, BURN_SCAN_LOOKBACK, per-chain *_RPC_URL.
#
# DELIVERY: base64 heredoc; decode + sha256 verify before replace; backup once
#   per file per run; idempotent; --revert to pristine.
#
# VERIFY AFTER: cd nexum-api && npx tsc --noEmit
# =============================================================================
set -euo pipefail
find_root() { local d="$PWD"; while [ "$d" != "/" ]; do [ -d "$d/nexum-api/src/services/bridge" ] && { echo "$d"; return; }; d="$(dirname "$d")"; done; [ -d "$HOME/AfriFX/Nexum-main/nexum-api/src/services/bridge" ] && { echo "$HOME/AfriFX/Nexum-main"; return; }; [ -d "$HOME/AfriFX/nexum-api/src/services/bridge" ] && { echo "$HOME/AfriFX"; return; }; return 1; }
ROOT="$(find_root)" || { echo "ERROR: repo root not found (needs nexum-api/src/services/bridge)."; exit 1; }
echo "Repo root: $ROOT"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP_DIR="$ROOT/.nexum-burn-scanner-backups"
BR="$ROOT/nexum-api/src/services/bridge"
RP_PATH="$BR/repository.ts";  RP_SHA="63ce530b7829d52aa45245a2554189dfc615bbb4153b838a718d284e8fc8ad83"; RP_B64=""
RC_PATH="$BR/reconciler.ts";  RC_SHA="6a900cf18d2187a073342a891e229e78e1b1773d373f106232e5c2040377c849"; RC_B64=""
SC_PATH="$BR/burnScanner.ts"; SC_SHA="5accb43b07c486630ab77b95f37ff4962b490d13a08d52496dae28669f2cf313"; SC_B64=""

restore_edit() { local base="$1" dest="$2" p; p="$(ls -1tr "$BACKUP_DIR"/"$base".* 2>/dev/null | grep -v '\.CREATED$' | head -n1 || true)"; if [ -n "${p:-}" ] && [ -f "$p" ]; then cp -f "$p" "$dest" && echo "restored $base"; else echo "no backup for $base"; fi; }
revert() {
  echo "== REVERT =="
  if [ -f "$BACKUP_DIR/burnScanner.ts.CREATED" ]; then [ -f "$SC_PATH" ] && rm -f "$SC_PATH" && echo "removed burnScanner.ts (created by this script)"; fi
  restore_edit "repository.ts" "$RP_PATH"
  restore_edit "reconciler.ts" "$RC_PATH"
  rm -f "$BACKUP_DIR"/*.* 2>/dev/null || true; rmdir "$BACKUP_DIR" 2>/dev/null || true
  echo "revert complete."
}
if [ "${1:-}" = "--revert" ]; then revert; exit 0; fi
mkdir -p "$BACKUP_DIR"
write_new() { local name="$1" path="$2" sha="$3" b64="$4"; local tmp; tmp="$(mktemp)"; printf '%s' "$b64" | base64 -d > "$tmp" || { echo "decode fail $name"; rm -f "$tmp"; exit 1; }; local got; got="$(sha256sum "$tmp" | cut -d' ' -f1)"; [ "$got" = "$sha" ] || { echo "ERROR checksum $name"; echo " expected $sha"; echo " got      $got"; rm -f "$tmp"; exit 1; }; echo "  verified $name"; [ -f "$path" ] || { touch "$BACKUP_DIR/$(basename "$path").CREATED"; echo "  $name is new"; }; mkdir -p "$(dirname "$path")"; mv -f "$tmp" "$path"; echo "  wrote $path"; }
write_edit() { local name="$1" path="$2" sha="$3" b64="$4"; local tmp; tmp="$(mktemp)"; printf '%s' "$b64" | base64 -d > "$tmp" || { echo "decode fail $name"; rm -f "$tmp"; exit 1; }; local got; got="$(sha256sum "$tmp" | cut -d' ' -f1)"; [ "$got" = "$sha" ] || { echo "ERROR checksum $name"; echo " expected $sha"; echo " got      $got"; rm -f "$tmp"; exit 1; }; echo "  verified $name"; [ -f "$path" ] && [ ! -f "$BACKUP_DIR/$(basename "$path").$STAMP" ] && cp -f "$path" "$BACKUP_DIR/$(basename "$path").$STAMP" && echo "  backed up $name"; mv -f "$tmp" "$path"; echo "  wrote $path"; }
echo "== APPLY bridge burn-scanner =="
write_new  "burnScanner.ts" "$SC_PATH" "$SC_SHA" "$SC_B64"
write_edit "repository.ts"  "$RP_PATH" "$RP_SHA" "$RP_B64"
write_edit "reconciler.ts"  "$RC_PATH" "$RC_SHA" "$RC_B64"
echo
echo "== DONE - burn-scanner runs on the existing bridge reconciler cron. =="
echo "Verify: cd $ROOT/nexum-api && npx tsc --noEmit"
echo "Revert: bash $(basename "$0") --revert"
